import{_ as t,a0 as r,w as o,s as l,ao as m,I as n,x as s,a1 as p,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"7-Zip vs WinRAR vs WinZIP： 最好的文件壓縮工具對比 | LCTT x X-CMD","titleTemplate":false,"description":"7-Zip vs WinRAR vs WinZIP： 最好的文件壓縮工具對比 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7-Zip vs WinRAR vs WinZIP： 最好的文件壓縮工具對比 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7-Zip vs WinRAR vs WinZIP： 最好的文件壓縮工具對比 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161026 7-Zip vs WinRAR vs WinZIP The Best Tool for File Compression","title":"7-Zip vs WinRAR vs WinZIP： 最好的文件壓縮工具對比","tag":"201611","desc":""},"relativePath":"201611/20161026 7-Zip vs WinRAR vs WinZIP The Best Tool for File Compression.md","filePath":"[post].md"}'),d={name:"201611/20161026 7-Zip vs WinRAR vs WinZIP The Best Tool for File Compression.md"};function f(w,i,Z,h,R,W){const e=r("Link");return o(),l("div",null,[i[13]||(i[13]=m('<h1 id="_7-zip-vs-winrar-vs-winzip-最好的文件壓縮工具對比" tabindex="-1">7-Zip vs WinRAR vs WinZIP： 最好的文件壓縮工具對比 <a class="header-anchor" href="#_7-zip-vs-winrar-vs-winzip-最好的文件壓縮工具對比" aria-label="Permalink to “7-Zip vs WinRAR vs WinZIP： 最好的文件壓縮工具對比”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/best-file-compression.jpg" alt=""></p><p>在拳擊界裏有阿里、弗雷澤和福爾曼。在遊戲機界裏有任天堂、索尼和微軟，在 PC 壓縮軟件領域裏有7-Zip、WinRAR 和 WinZIP。我要發動這個軟件的對決嗎？也許，不管怎麼説它一直是一個重要的軟件。</p><p>這三個程序有同樣的功能，你可以獲取一堆你電腦上的文件然後打包壓縮它們到一個歸檔，壓縮它們的文件大小，直到有人決定取出它們。它們都易於使用，但是哪個做的更好？我拿它們做了一個測試來找出答案。</p><p>注意：雖然還有很多其它的壓縮格式，但 Winzip、7Zip 和 WinRAR 是三個 Windows 上最流行的壓縮工具。那就是為什麼我們只對比這三個工具。</p><p>注意：為了測試，我壓縮了一堆未壓縮的視頻文件，總計佔用 1.3GB 的空間。我還使用最好的壓縮設置來測試它們而不是默認的設置。對於每個項目，我描述瞭如何使這些設置。</p><h3 id="_7-zip-出了免費這一大招" tabindex="-1">7-Zip 出了免費這一大招 <a class="header-anchor" href="#_7-zip-出了免費這一大招" aria-label="Permalink to “7-Zip 出了免費這一大招”">​</a></h3><p>值得一説的是，開源的 7-Zip 是免費的，沒有附加條件的這一塊已經擁有優勢。WinRAR 本質上是免費的，除了你必須忍受每次打開它時惱人的提示告訴你試用過期了。（你付款主要是為了擺脱這個提示。）而另一方面，WinZip 在試用期結束後會鎖定你。</p><h3 id="winzip" tabindex="-1">WinZip <a class="header-anchor" href="#winzip" aria-label="Permalink to “WinZip”">​</a></h3><p>在今天的世界裏，我們莫名其妙地期望的一切與軟件相關的都是免費的，與我們的預期相悖，WinZip 大膽的在試用期後收費 £25.95。不過，也許是因為它比競爭對手做得更好，才讓其標上這麼大膽的價格標籤？讓我們來看看。</p><p>WinZip 有一個選項可以把文件壓縮成 .zipx 格式，它生成擁有比 .zip 和其它競爭者更高的壓縮比。要做到這一點，選擇並右鍵單擊要壓縮文件，然後單擊“WinZip - &gt;添加到壓縮”文件。當 WinZip 打開後，選擇“壓縮類型”下的“.Zipx”，然後開始壓縮。</p><p>這裏是我們使用兩種 WinZip 壓縮方法的結果：</p><ul><li>.Zip: 855MB (34% 壓縮)</li><li>.Zipx: 744MB (43% 壓縮)</li></ul><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/compression-software-compared-winzip.png" alt="compression-software-compared-winzip"></p><h3 id="winrar" tabindex="-1">WinRAR <a class="header-anchor" href="#winrar" aria-label="Permalink to “WinRAR”">​</a></h3><p>WinRAR 壓縮的文件是 RAR 格式（這是它自己獨有的名字），也有一些技巧可以獲得最大的壓縮。</p><p>一旦你選擇要壓縮文件，右擊它們，請單擊“添加到壓縮文件”，然後勾選“創建可靠的歸檔”複選框。下一步，單擊“壓縮方式”的下拉列表，將其更改為“最佳”。WinRAR 的還有一個叫做 RAR5 的明顯增強的壓縮方法，所以我測試了這一點，以及標準的壓縮方法。下面是我們得到的：</p><ul><li>.rar: 780MB (40% 壓縮)</li><li>.rar5: 778MB (40% 壓縮)</li></ul><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/compression-software-compared-winrar.png" alt="compression-software-compared-winrar"></p><h3 id="_7-zip" tabindex="-1">7-Zip <a class="header-anchor" href="#_7-zip" aria-label="Permalink to “7-Zip”">​</a></h3><p>它沒有評估版或付費版，但是隨之而來的壓縮質量如何？要正確測試它，選擇要壓縮文件，右擊它們，選擇“添加到壓縮文件”，然後選擇7-Zip。</p><p>在新的窗口中更改壓縮方法 LZMA2（如果你有一個 4 核或更強的 CPU），壓縮級別設置為極端，然後壓縮！這裏的結果：</p><ul><li>.7z: 758MB (42% 壓縮)</li></ul><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/compression-software-compared-7zip.png" alt="compression-software-compared-7zip"></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>基於以上結果，我將繼續堅持使用 7-zip。和技術上的“贏家” WinZip 比，這 1% 差別的壓縮水平不足以為此花錢。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/compression-software-compared-windows.png" alt="compression-software-compared-windows"></p><p>或許你並不想下載任何第三方軟件，在這種情況下，你可以使用 Windows 的內置壓縮工具。要使用它，只需右鍵單擊任何你想壓縮的文件，選擇“發送到”，然後“壓縮文件夾”。它只把文件壓縮到 892 MB的水平（31％），但它更便捷快速，而且是免費和內置的，所以我們還有抱怨嗎？</p><hr>',29)),n("p",null,[i[1]||(i[1]=s("via: ",-1)),p(e,{href:"https://www.maketecheasier.com/7-zip-vs-winrar-vs-winzip/"},{default:a(()=>[...i[0]||(i[0]=[s("https://www.maketecheasier.com/7-zip-vs-winrar-vs-winzip/",-1)])]),_:1})]),n("p",null,[i[5]||(i[5]=s("作者：",-1)),p(e,{href:"https://www.maketecheasier.com/author/robzak/"},{default:a(()=>[...i[2]||(i[2]=[s("Robert Zak",-1)])]),_:1}),i[6]||(i[6]=s(" 譯者：",-1)),p(e,{href:"https://github.com/wyangsun"},{default:a(()=>[...i[3]||(i[3]=[s("wyangsun",-1)])]),_:1}),i[7]||(i[7]=s(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[4]||(i[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[10]||(i[10]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[8]||(i[8]=[s("LCTT",-1)])]),_:1}),i[11]||(i[11]=s(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:a(()=>[...i[9]||(i[9]=[s("Linux中國",-1)])]),_:1}),i[12]||(i[12]=s(" 榮譽推出",-1))])])}const c=t(d,[["render",f]]);export{T as __pageData,c as default};
